def month_of(day):
    return Period(day.replace(day=1), day.replace(day=last_day(day.year, day.month)))


# -- init, db, serve ---------------------------------------------------------


def cmd_init(ctx, pos, opts):
    from tallybook.storage import LATEST_VERSION, Store

    fresh = not os.path.exists(ctx.db) or (os.path.isfile(ctx.db) and os.path.getsize(ctx.db) == 0)
    with Store.open(ctx.db, create=True) as store:
        if fresh:
            ctx.write("created %s (version %d)\n" % (ctx.db, store.version))
            return 0
        old = store.version
        if old < LATEST_VERSION:
            store.migrate()
            ctx.write("migrated %s from version %d to %d\n" % (ctx.db, old, store.version))
        else:
            ctx.write("%s is up to date (version %d)\n" % (ctx.db, old))
    return 0


def cmd_db_version(ctx, pos, opts):
    with ctx.store() as store:
        ctx.write("%d\n" % store.version)


def cmd_db_migrate(ctx, pos, opts):
    from tallybook.storage import LATEST_VERSION

    with ctx.store() as store:
        applied = store.migrate()
        if applied:
            for v in applied:
                ctx.write("applied version %d\n" % v)
        else:
            ctx.write("database is up to date (version %d)\n" % LATEST_VERSION)


def cmd_db_info(ctx, pos, opts):
    with ctx.store() as store:
        info = store.info()
    if opts.get("--json"):
        ctx.write(to_json(info))
        return
    for key in ("path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"):
        ctx.write("%s: %s\n" % (key, info[key]))


def cmd_db_check(ctx, pos, opts):
    with ctx.store() as store:
        problems = store.check()
    if not problems:
        ctx.write("ok\n")
        return 0
    ctx.write("".join(p + "\n" for p in problems))
    return 1


def cmd_db_backup(ctx, pos, opts):
    with ctx.store() as store:
        store.backup(pos[0])
    ctx.write("backed up to %s\n" % pos[0])


def cmd_serve(ctx, pos, opts):
    from tallybook.api.server import serve

    host = opts.get("--host", "127.0.0.1")
    port = whole(opts["--port"], "port") if "--port" in opts else 8765
    if port > 65535:
        raise CliError("invalid port %r: the largest is 65535" % opts["--port"])
    with ctx.store() as store:
        store.info()
    return serve(ctx.db, host=host, port=port, today=ctx.today_opt)


# -- accounts ----------------------------------------------------------------



def cmd_journal_export(ctx, pos, opts):
    with ctx.store() as store:
        ctx.write(format_journal(store.journal()))


def cmd_journal_import(ctx, pos, opts):
    journal = journal_from(pos[0])
    with ctx.store() as store:
        store.load_journal(journal)
    ctx.write(
        "imported %d accounts, %d rates, %d transactions\n"
        % (len(journal.accounts), len(journal.rates), len(journal.transactions))
    )


# -- bank statements, profiles, rules ---------------------------------------


def cmd_import(ctx, pos, opts):
    if ("--profile" in opts) == ("--profile-file" in opts):
        raise UsageError("give exactly one of --profile and --profile-file")
    text = read_text(pos[0])
    if "--profile-file" in opts:
        profile = parse_profile(read_text(opts["--profile-file"]))
    with ctx.store() as store:
        if "--profile" in opts:
            profile = parse_profile(store.profile_text(opts["--profile"]))
        outcome = store.import_csv(text, profile, apply_rules=not opts.get("--no-rules"))
    if outcome.errors:
        raise CliError(
            "%d rows could not be imported, nothing was imported" % len(outcome.errors),
            ["row %d: %s" % (n, msg) for n, msg in outcome.errors],
        )
    ctx.write("imported %d transactions, %d duplicates\n" % (len(outcome.added), len(outcome.duplicates)))


def cmd_profile_add(ctx, pos, opts):
    text = read_text(pos[1])
    with ctx.store() as store:
        store.set_profile(pos[0], text)
    ctx.write("stored profile %s\n" % pos[0])


def cmd_profile_list(ctx, pos, opts):
    with ctx.store() as store:
        names = store.profiles()
    if opts.get("--json"):
        ctx.write(to_json(names))
    else:
        ctx.write("".join(n + "\n" for n in names))
    with ctx.store() as store:
        store.set_rate(pos[0], pos[1], pos[2], on)
    ctx.write("set 1 %s = %s %s on %s\n" % (pos[0], pos[2], pos[1], format_date(on)))


def cmd_rate_list(ctx, pos, opts):
    with ctx.store() as store:
        rows = store.rate_rows()
    if opts.get("--json"):
        ctx.write(
            to_json([{"from": s, "to": d, "date": format_date(o), "rate": t} for s, d, o, t in rows])
        )
    elif rows:
        ctx.write(render_table(["From", "To", "Date", "Rate"], [[s, d, format_date(o), t] for s, d, o, t in rows], "lllr"))


def cmd_rate_remove(ctx, pos, opts):
