_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")
_KINDS = ("month", "quarter", "year")
_MONTHS_PER = {"month": 1, "quarter": 3, "year": 12}


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise BudgetError("invalid budget pattern %r: expected an account path whose segments may be *" % (pattern,))
    parts = pattern.split(":")
    for part in parts:
        if part != "*" and _SEGMENT.fullmatch(part) is None:
            raise BudgetError("invalid budget pattern %r: bad segment %r" % (pattern, part))
    return tuple(parts)


