        _check_pattern(self.pattern)
        if not isinstance(self.period_kind, str) or self.period_kind not in _KINDS:
            raise BudgetError("invalid period kind %r: expected month, quarter or year" % (self.period_kind,))
        if not isinstance(self.amount, Money):
            raise BudgetError("budget amount must be a Money, got %r" % (self.amount,))
        if self.amount.minor <= 0:
            raise BudgetError("budget amount must be greater than zero, got %s" % (self.amount,))
        if not is_date(self.start):
            raise BudgetError("budget start must be a datetime.date, got %r" % (self.start,))


@dataclass(frozen=True)
