            "actual": money_to_dict(self.actual),
            "remaining": money_to_dict(self.remaining),
            "percent": str(self.percent),
            "over": self.over,
            "accounts": [{"account": a, "amount": money_to_dict(m)} for a, m in self.accounts],
        }


def _month_index(d):
    return d.year * 12 + d.month - 1


def _bounds(kind, index):
    """First and last day of the calendar period of `kind` holding month `index` (a multiple of its length)."""
    year, month0 = divmod(index, 12)
    months = _MONTHS_PER[kind]
    end_year, end_month0 = divmod(index + months - 1, 12)
    return date(year, month0 + 1, 1), date(end_year, end_month0 + 1, last_day(end_year, end_month0 + 1))


def _slot(kind, d):
    months = _MONTHS_PER[kind]
    return _month_index(d) // months


def _allowance(budget, period):
    kind = budget.period_kind
    months = _MONTHS_PER[kind]
    first = _slot(kind, budget.start)
    lo = max(first, _slot(kind, period.start))
    hi = _slot(kind, period.end)
    if lo > hi:
        return None
    total = Fraction(0)
    ps, pe = period.start.toordinal(), period.end.toordinal()
    for slot in range(lo, hi + 1):
        s, e = _bounds(kind, slot * months)
        so, eo = s.toordinal(), e.toordinal()
        overlap = min(eo, pe) - max(so, ps) + 1
        if overlap > 0:
            total += Fraction(overlap, eo - so + 1)
    value = total * budget.amount.minor
    return Money(round_div(value.numerator, value.denominator), budget.amount.currency)


def _matches(parts, path):
    segs = path.split(":")
    if len(segs) < len(parts):
        return False
    return all(p == "*" or p == s for p, s in zip(parts, segs))


def _percent(actual, allowance):
    if allowance == 0:
        return Decimal("0.0") if actual == 0 else Decimal("100.0")
    tenths = round_div(abs(actual) * 1000, abs(allowance))
    if (actual < 0) != (allowance < 0):
        tenths = -tenths
    sign = "-" if tenths < 0 else ""
    return Decimal("%s%d.%d" % (sign, abs(tenths) // 10, abs(tenths) % 10))


def budget_status(budgets, ledger, period):
    if not isinstance(ledger, Ledger):
        raise BudgetError("expected a Ledger, got %r" % (ledger,))
    if not isinstance(period, Period):
        raise BudgetError("expected a Period, got %r" % (period,))
    budgets = list(budgets)
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("expected a Budget, got %r" % (b,))
    spending = {}
    for tx, posting in ledger.postings():
        if not period.start <= tx.date <= period.end:
            continue
        path = posting.account
        if path != "Expenses" and not path.startswith("Expenses:"):
            continue
        amount = posting.amount
        by_cur = spending.setdefault(amount.currency, {})
        by_cur[path] = by_cur.get(path, 0) + amount.minor

    ordered = sorted(budgets, key=lambda b: (b.pattern, _KINDS.index(b.period_kind), b.start))
    lines = []
    for b in ordered:
        allowance = _allowance(b, period)
        if allowance is None:
            continue
        parts = _check_pattern(b.pattern)
        cur = b.amount.currency
        per_account = {p: v for p, v in spending.get(cur, {}).items() if v != 0 and _matches(parts, p)}
        total = sum(
            v for p, v in spending.get(cur, {}).items() if _matches(parts, p)
        )
        actual = Money(total, cur)
        lines.append(
            BudgetLine(
                b.pattern,
                b.period_kind,
                allowance,
                actual,
                allowance - actual,
                _percent(actual.minor, allowance.minor),
                actual.minor > allowance.minor,
                tuple((p, Money(v, cur)) for p, v in sorted(per_account.items())),
            )
        )
    return lines

