    return json_reply([transaction_to_dict(t) for t in txs])


# -- routing -----------------------------------------------------------------

_JSON = ("application/json",)
_IMPORT = ("text/csv", "text/plain", "application/json")
_REPORTS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def route(pieces):
    """Return {VERB: (handler, accepted body types)} for a path, or None when the path is unknown."""
    n = len(pieces)
    if any(p == "" for p in pieces):
        return None
    head = pieces[0]
    if n == 1:
        table = {
            "health": {"GET": (h_health, _JSON)},
            "accounts": {"GET": (h_accounts_list, _JSON), "POST": (h_accounts_add, _JSON)},
            "transactions": {"GET": (h_tx_list, _JSON), "POST": (h_tx_add, _JSON)},
            "rates": {"GET": (h_rates_list, _JSON), "PUT": (h_rates_put, _JSON), "DELETE": (h_rates_delete, _JSON)},
            "budgets": {
                "GET": (h_budgets_list, _JSON),
                "POST": (h_budgets_add, _JSON),
                "DELETE": (h_budgets_delete, _JSON),
            },
            "recurring": {
                "GET": (h_recurring_list, _JSON),
                "POST": (h_recurring_add, _JSON),
                "DELETE": (h_recurring_delete, _JSON),
            },
            "rules": {"GET": (h_rules_get, _JSON), "PUT": (h_rules_put, _JSON)},
            "export": {"GET": (h_export, _JSON)},
            "import": {"POST": (h_import, _IMPORT)},
        }
        return table.get(head)
    if n == 2:
        second = pieces[1]
        if head == "accounts":
            return {"GET": (h_account_get, _JSON)}
        if head == "transactions" and _DIGITS.fullmatch(second):
            return {"GET": (h_tx_get, _JSON), "DELETE": (h_tx_delete, _JSON)}
        if head == "budgets" and second == "status":
            return {"GET": (h_budgets_status, _JSON)}
        if head == "recurring" and second == "materialize":
            return {"POST": (h_materialize, _JSON)}
        if head == "reports" and second in _REPORTS:
            return {"GET": (h_report, _JSON)}
        return None
    if n == 3 and head == "accounts" and pieces[2] == "close":
        return {"POST": (h_account_close, _JSON)}
    return None


# -- the HTTP layer ----------------------------------------------------------


def _reason(status):
    try:
        return HTTPStatus(status).phrase
    except ValueError:
        return "Error"


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    timeout = REQUEST_TIMEOUT
    server_version = "tallybook"
    sys_version = ""

    def log_message(self, *args, **kwargs):
        pass

    def log_request(self, *args, **kwargs):
        pass

    def log_error(self, *args, **kwargs):
        pass

    def handle(self):
        try:
            self.close_connection = True
            self.handle_one_request()
        except Exception:
            pass

    def send_error(self, code, message=None, explain=None):
        self.close_connection = True
        self._send(400, JSON_TYPE, to_json({"error": "malformed request"}).encode("utf-8"))

    def handle_one_request(self):
        self.close_connection = True
        self._remaining = 0
        self.raw_requestline = self.rfile.readline(65537)
        if not self.raw_requestline:
            return
        if len(self.raw_requestline) > 65536:
            self.requestline = self.request_version = self.command = ""
            self.send_error(400)
            return
        if not self.parse_request():
            return
        self.close_connection = True
        words = self.requestline.split()
        if len(words) != 3:
            self.send_error(400)
            return
        self._dispatch(words[1])

    def _lenient_length(self):
        values = self.headers.get_all("Content-Length") or []
        if len(set(values)) == 1 and _DIGITS.fullmatch(values[0]) and values[0].isascii():
            return min(int(values[0].lstrip("0") or "0"), MAX_DRAIN)
        return 0

    def _drain(self):
        remaining, self._remaining = self._remaining, 0
        if remaining <= 0:
            return
        old = self.connection.gettimeout()
        try:
            self.connection.settimeout(min(old or 2.0, 2.0))
            while remaining > 0:
                chunk = self.rfile.read(min(remaining, 65536))
                if not chunk:
                    break
                remaining -= len(chunk)
        except (OSError, ValueError):
            pass
        finally:
            try:
                self.connection.settimeout(old)
            except OSError:
                pass

    def _send(self, status, ctype, body, allow=None):
        self._drain()
        head = [
            "HTTP/1.1 %d %s" % (status, _reason(status)),
            "Content-Type: " + ctype,
            "Content-Length: %d" % len(body),
            "Connection: close",
        ]
        if allow:
            head.append("Allow: " + allow)
        data = ("\r\n".join(head) + "\r\n\r\n").encode("latin-1")
        if self.command != "HEAD":
            data += body
        try:
            self.wfile.write(data)
            self.wfile.flush()
        except OSError:
            pass

    def _error(self, status, message, allow=None):
        self._send(status, JSON_TYPE, to_json({"error": message or "error"}).encode("utf-8"), allow)

    def _read_body(self, length):
        chunks = []
        remaining = length
        while remaining > 0:
            chunk = self.rfile.read(min(remaining, 65536))
            if not chunk:
                raise HttpError(400, "request body is shorter than its Content-Length")
            chunks.append(chunk)
            remaining -= len(chunk)
            self._remaining -= len(chunk)
        return b"".join(chunks)

    def _dispatch(self, target):
        self._remaining = self._lenient_length()
        try:
            reply = self._handle(target)
        except HttpError as exc:
            self._error(exc.status, exc.message, exc.allow)
            return
        except TallybookError as exc:
            self._error(_STATUS.get(exc.code, 400), exc.message or "error")
            return
        except socket.timeout:
            self._error(400, "request body was not received in time")
            return
        except OverflowError:
            self._error(400, "number out of range")
            return
        except MemoryError:
            self._error(500, "out of memory")
            return
        except Exception:
            self._error(500, "internal error")
            return
        self._send(*reply)

    def _handle(self, target):
        pieces, raw_query = split_target(target)
        verbs = route(pieces) if pieces is not None else None
        if verbs is None:
            raise HttpError(404, "no such path")
        if self.command not in verbs:
            raise HttpError(405, "method not allowed: %s" % self.command, ", ".join(sorted(verbs)))
        handler, types = verbs[self.command]
        values = self.headers.get_all("Content-Length") or []
        length = 0
        if values:
            if len(set(values)) != 1 or _DIGITS.fullmatch(values[0]) is None or not values[0].isascii():
                raise HttpError(400, "invalid Content-Length")
            length = int(values[0].lstrip("0") or "0")
        body = b""
        content_type = ""
        if self.command in ("POST", "PUT"):
            if length > MAX_BODY:
                raise HttpError(413, "request body is larger than %d bytes" % MAX_BODY)
            body = self._read_body(length)
            content_type = (self.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
            if body and content_type not in types:
                raise HttpError(415, "unsupported content type: expected %s" % " or ".join(types))
        rq = Request(self.server, self.command, pieces, raw_query, body)
        rq.content_type = content_type
        return handler(rq)


class ApiServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True
    request_queue_size = 128

    def __init__(self, address, handler, db_path, today):
        self.db_path = db_path
        self.today = today
        self._active = 0
        self._cond = threading.Condition()
        if ":" in address[0]:
            self.address_family = socket.AF_INET6
        super().__init__(address, handler)

    def process_request(self, request, client_address):
        with self._cond:
            self._active += 1
        try:
            super().process_request(request, client_address)
        except BaseException:
            self._finished()
            raise

    def process_request_thread(self, request, client_address):
        try:
            super().process_request_thread(request, client_address)
        finally:
            self._finished()

    def _finished(self):
        with self._cond:
            self._active -= 1
            self._cond.notify_all()

    def wait_idle(self, timeout):
        with self._cond:
            self._cond.wait_for(lambda: self._active <= 0, timeout)

    def handle_error(self, request, client_address):
        pass


def make_server(db_path, host="127.0.0.1", port=0, today=None, timeout=REQUEST_TIMEOUT):
    """Bind a server (no thread, no output); the caller runs serve_forever() and shutdown()."""
    handler = type("BoundHandler", (Handler,), {"timeout": timeout})
    try:
        return ApiServer((host, port), handler, db_path, today)
    except OSError as exc:
        raise ConflictError("cannot listen on %s:%s: %s" % (host, port, exc.strerror or exc)) from None


def serve(db_path, host="127.0.0.1", port=0, today=None):
    store = Store.open(db_path)
    try:
        store.info()
    finally:
        store.close()
    server = make_server(db_path, host, port, today)
    previous = []
    try:
        if threading.current_thread() is threading.main_thread():

            def stop(signum, frame):
                threading.Thread(target=server.shutdown, daemon=True).start()

            for name in ("SIGINT", "SIGTERM"):
                sig = getattr(signal, name, None)
                if sig is not None:
                    previous.append((sig, signal.signal(sig, stop)))
        shown = server.server_address[0]
        if ":" in shown:
            shown = "[%s]" % shown
        sys.stdout.write("tallybook listening on http://%s:%d\n" % (shown, server.server_address[1]))
        sys.stdout.flush()
        server.serve_forever()
    finally:
        for sig, old in previous:
            try:
                signal.signal(sig, old)
            except (OSError, ValueError, TypeError):
                pass
        server.server_close()
        server.wait_idle(2.0)
    return 0

